void sCaplinkManager::cCaplinkWebsocketListener::onNotifyChat(nCaplink::WebsocketNotifyChat* notify) {
    if (notify == nullptr) {
        return;
    }
    sCaplinkManager::getInstance()->addChatList(notify);
}

