void sCaplinkManager::cCaplinkWebsocketListener::onClose() {
    mIsConnected = false;
    mIsError = false;
    mIsRegistDevice = false;
    if (sCaplinkManager::getInstance()->mpCaplink == nullptr) {
        return;
    }
    if (!sCaplinkManager::getInstance()->mpCaplink->getRetry()) {
        return;
    }
    mIsRegistDevice = true;
}

